package gg.eternal.core.hud;
import gg.eternal.core.EternalCore; import gg.eternal.core.state.InputState; import net.minecraft.client.Minecraft;
public final class HudRenderer { private static final String[] MODULES={"FPS","CPS","Keystrokes","Coordinates","Ping","Speed","Direction","Memory","Session"}; public static void install(){} public static String value(String n){Minecraft mc=Minecraft.getInstance();if(n.equals("FPS"))return "FPS "+mc.getFps();if(n.equals("CPS"))return "CPS "+InputState.leftCps()+" | "+InputState.rightCps();if(mc.player==null)return n+" --";return switch(n){case "Coordinates"->String.format("XYZ %.0f / %.0f / %.0f",mc.player.getX(),mc.player.getY(),mc.player.getZ());case "Ping"->"PING "+(mc.getConnection()!=null&&mc.getConnection().getPlayerInfo(mc.player.getUUID())!=null?mc.getConnection().getPlayerInfo(mc.player.getUUID()).getLatency():0)+"ms";case "Speed"->String.format("SPEED %.2f",Math.sqrt(mc.player.getDeltaMovement().x*mc.player.getDeltaMovement().x+mc.player.getDeltaMovement().z*mc.player.getDeltaMovement().z)*20);case "Direction"->"DIR "+Math.round(mc.player.getYRot())+"°";case "Memory"->{Runtime r=Runtime.getRuntime();yield "MEM "+((r.totalMemory()-r.freeMemory())/1048576)+" / "+(r.maxMemory()/1048576)+" MB";}case "Session"->"SESSION "+format(EternalCore.sessionMillis());case "Keystrokes"->"WASD";default->n;};} private static String format(long ms){long s=ms/1000;return String.format("%02d:%02d:%02d",s/3600,(s/60)%60,s%60);} public static String[] modules(){return MODULES;} }
